-- Read-only checks on live before the 23 Nov 2026 rollout. Run each part on its own
-- in the Supabase SQL editor (project NexgApp) and paste the results to the rollout chat.
-- None changes anything; none needs a password or key.
-- See docs/database/live-rollout-2026-11-23.md, runbook step 2.

-- ─────────────────────────────────────────────────────────────── K. is live's history the local copy's?
-- Added 23 Nov by the live-db-rollout chat. Read-only. The owner's local stack
-- (container supabase_db_nexg, built 8 Nov) holds 280 versions ending at
-- 20261111001700, like live, with the names and SQL of the 18 versions in the
-- 20261111 block. If live gives the same fingerprints, live ran exactly that SQL.
-- Expected:  versions = 280, all_280 = cce74d301c9a692e4ad8e7cb13504f98,
--            before_1111 = 5b16d17090131669c3825f139cf2aa5b
select count(*) as versions,
       md5(string_agg(version || ':' || coalesce(name, '') || ':' || md5(coalesce(array_to_string(statements, E'\n'), '')), ',' order by version)) as all_280,
       md5(string_agg(version || ':' || coalesce(name, '') || ':' || md5(coalesce(array_to_string(statements, E'\n'), '')), ',' order by version)
           filter (where version < '20261111000000')) as before_1111
from supabase_migrations.schema_migrations;

-- K2. Only if K differs: one row per version from 20261111 on, to compare with the audit's table.
select version, name, md5(coalesce(array_to_string(statements, E'\n'), '')) as sql_md5
from supabase_migrations.schema_migrations
where version >= '20261111000000' or version in ('20261102000000', '20261110000000')
order by version;

-- ─────────────────────────────────────────────────────────────── G. would any missing migration stop the push?
-- Added 23 Nov by the live-db-rollout chat. Read-only.
-- Every object a missing migration creates WITHOUT "if not exists" / "or replace".
-- If one already exists live, `db push` stops at that file with "already exists".
