) as v(version, kind, obj)
where case v.kind
  when 'table'    then to_regclass(v.obj) is not null
  when 'index'    then to_regclass(v.obj) is not null
  when 'sequence' then to_regclass(v.obj) is not null
  when 'view'     then to_regclass(v.obj) is not null
  when 'type'     then to_regtype(v.obj) is not null
  when 'domain'   then to_regtype(v.obj) is not null
  when 'schema'   then exists (select 1 from pg_namespace where nspname = v.obj)
  when 'function' then exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
                               where n.nspname = split_part(v.obj, '.', 1) and p.proname = split_part(v.obj, '.', 2))
  when 'column'   then exists (select 1 from information_schema.columns
                               where table_schema = split_part(v.obj, '.', 1) and table_name = split_part(v.obj, '.', 2)
                                 and column_name = split_part(v.obj, '.', 3))
  when 'policy'   then exists (select 1 from pg_policies
                               where schemaname = split_part(split_part(v.obj, '/', 1), '.', 1)
                                 and tablename = split_part(split_part(v.obj, '/', 1), '.', 2)
                                 and policyname = split_part(v.obj, '/', 2))
  when 'trigger'  then exists (select 1 from pg_trigger t join pg_class c on c.oid = t.tgrelid
                               join pg_namespace n on n.oid = c.relnamespace
                               where n.nspname = split_part(split_part(v.obj, '/', 1), '.', 1)
                                 and c.relname = split_part(split_part(v.obj, '/', 1), '.', 2)
                                 and t.tgname = split_part(v.obj, '/', 2) and not t.tgisinternal)
  when 'constraint' then exists (select 1 from pg_constraint k join pg_class c on c.oid = k.conrelid
                               join pg_namespace n on n.oid = c.relnamespace
                               where n.nspname = split_part(split_part(v.obj, '/', 1), '.', 1)
                                 and c.relname = split_part(split_part(v.obj, '/', 1), '.', 2)
                                 and k.conname = split_part(v.obj, '/', 2))
  else false end
order by v.version, v.kind, v.obj;

-- ─────────────────────────────────────────────────────────────── H. is a missing migration's code already live?
-- Added 23 Nov by the live-db-rollout chat. Read-only.
-- For every function a missing migration defines: does the live database already
-- have a function of that name, and is its body byte-for-byte the file's body
-- (md5 of pg_proc.prosrc; both LF and CRLF line endings count)?
-- One row per migration with at least one function whose exact code is already live.
-- Expected: rows only for 20261113000200 to 20261113001000 (the hosts workspace files).
--   identical = functions = that migration's code already ran live (a repeat).
--   identical = 0          = older versions exist; the migration replaces them (normal).
select v.version,
       count(distinct v.fn)                                       as functions,
       count(distinct v.fn) filter (where l.fn is not null)       as present_live,
       count(distinct v.fn) filter (where l.same)                 as identical,
       string_agg(distinct v.fn, ', ') filter (where l.same)      as identical_functions
