) as v(version, fn, md5_lf, md5_crlf)
left join lateral (
  select v.fn, bool_or(md5(p.prosrc) in (v.md5_lf, v.md5_crlf)) as same
  from pg_proc p join pg_namespace n on n.oid = p.pronamespace
  where n.nspname = split_part(v.fn, '.', 1) and p.proname = split_part(v.fn, '.', 2)
  group by 1
) l on true
group by v.version
having count(distinct v.fn) filter (where l.same) > 0
order by v.version;

-- ─────────────────────────────────────────────────────────────── I. which file ran under the shared numbers?
-- Added 23 Nov by the live-db-rollout chat. Read-only. One row, all true/false.
-- 20261102000000 was used by two files (food onboarding on main; the connector
-- foundation before it was renumbered 000050). 20261111000000 by three.
-- 20260101021800 is missing from live's history but a commit says it ran.
select
  exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'catalogue_item' and column_name = 'portion_size') as food_onboarding_ran,
  to_regclass('public.connector_adapter') is not null                                   as connector_foundation_ran,
  to_regtype('public.connector_family') is not null                                     as connector_types_exist,
  exists (select 1 from pg_enum e join pg_type t on t.oid = e.enumtypid
          where t.typname = 'merchant_category' and e.enumlabel = 'activities_games_sports') as activities_enum_ran,
  exists (select 1 from public.category_config where category::text = 'activities_games_sports') as activities_config_ran,
  exists (select 1 from pg_proc where proname = 'cron_merchant_application_operation_redact') as hardening_pr59_ran,
  exists (select 1 from public.wiring_audit_exempt where function_name = 'rpc_connector_outbox_claim') as main_connector_exemption_ran,
  exists (select 1 from pg_proc where proname = 'rpc_staff_reset_credentials')          as staff_reset_fn_exists,
  (select string_agg(version || ' ' || coalesce(name, '?'), ', ' order by version)
     from supabase_migrations.schema_migrations
    where version in ('20261102000000', '20261102000050', '20261111000000', '20260101021800')) as live_names;

-- ─────────────────────────────────────────────────────────────── J. rows the push changes (adds to E)
-- Added 23 Nov by the live-db-rollout chat. Read-only counts.
select 'payments with provider paystack (any)' as what, count(*) from public.payment where provider::text = 'paystack'
union all select 'units with no property (20270220000100 creates one each)', count(*) from public.unit where property_id is null
union all select 'orders (fraud_checks runs a first sweep over them at once)', count(*) from public."order"
union all select 'riders (fraud_checks sweep)', count(*) from public.rider
union all select 'paystack payments with no reference (remove_paystack makes them unassigned)', count(*) from public.payment where provider::text = 'paystack' and provider_ref is null
union all select 'merchants with no city (merchants_default_city sets Nairobi)', count(*) from public.merchant where city_id is null
union all select 'merchants (master_categories may move their category)', count(*) from public.merchant
union all select 'listed units (host_listing_details_and_publish publishes them)', count(*) from public.unit where listed
union all select 'fraud signals (fraud_checks changes the kind column and backfills)', count(*) from public.fraud_signal
union all select 'branches with a pin (precise_branch_locations re-measures their area)', count(*) from public.merchant_branch where latitude is not null
union all select 'live shops', count(*) from public.merchant where status::text = 'live'
union all select 'merchants on activities_games_sports (rollout-pre-push.sql switches that category off)', count(*) from public.merchant where category::text = 'activities_games_sports' or category_key = 'activities_games_sports';
